 const v=new THREE.Vector3();function frame(now){requestAnimationFrame(frame);if(paused||document.hidden)return;const t=now/1000;if(animation){const f=Math.min(1,(now-animation.time)/1100),s=f*f*(3-2*f);camera.position.lerpVectors(animation.from,animation.to,s);controls.target.lerpVectors(animation.targetFrom,animation.targetTo,s);if(f===1)animation=null;}controls.update();core.rotation.y=reduced?0:t*.18;for(const n of nodes){if(!reduced){n.gemGroup.position.y=.6+Math.sin(t*.75+n.phase)*.11;n.gemGroup.rotation.y=t*.12+n.phase;n.particles.rotation.y=t*.08;}v.copy(n.pos);v.y-=.7;v.project(camera);n.label.style.left=`${(v.x*.5+.5)*innerWidth}px`;n.label.style.top=`${(-v.y*.5+.5)*innerHeight}px`;n.label.hidden=v.z>1||v.z< -1||Math.abs(v.x)>1.1||Math.abs(v.y)>1.1;}renderer.render(scene,camera);}requestAnimationFrame(frame);
